// Picks OpenF1's latest session once its data is free: OpenF1 serves a session's data without an
// account from 30 minutes after it ends (live data needs the paid Sponsor tier). Runs up to
// MAX_HOURS after the end, so a late radio release is still caught.
const MAX_HOURS = 12;
const s = $input.all().map((i) => i.json).pop();
if (!s || !s.date_end) return [];
const freeFrom = new Date(s.date_end).getTime() + 30 * 60 * 1000;
const now = Date.now();
if (now < freeFrom || now > freeFrom + MAX_HOURS * 3600 * 1000) return [];
return [{ json: { session_key: s.session_key, label: `${s.year} ${s.circuit_short_name} ${s.session_name}` } }];

// Keeps only the clips not reported before (seen URLs in the workflow's static data, saved on
// active runs) and builds one email for the batch. The driver comes from the MP3 file name
// (e.g. VER_3_20261121_212748.mp3); times are UTC.
const label = $('Session ready?').first().json.label;
const clips = $input.all().map((i) => i.json).filter((c) => c.recording_url);
const state = $getWorkflowStaticData('global');
const seen = new Set(state.seen ?? []);
const fresh = clips.filter((c) => !seen.has(c.recording_url)).sort((a, b) => a.date.localeCompare(b.date));
state.seen = [...new Set([...(state.seen ?? []), ...clips.map((c) => c.recording_url)])].slice(-2000);
if (!fresh.length) return [];
const rows = fresh.map((c) => {
  const driver = (c.recording_url.split('/').pop().match(/^([A-Z]{3})_/) || [])[1] || `#${c.driver_number}`;
  return `<li><b>${driver}</b> · ${c.date.slice(11, 19)} UTC · <a href="${c.recording_url}">escuchar</a></li>`;
}).join('');
return [{ json: {
  subject: `Radio ${label}: ${fresh.length} clip${fresh.length === 1 ? '' : 's'} nuevo${fresh.length === 1 ? '' : 's'}`,
  html: `<p>${label} · ${fresh.length} clips de radio publicados por F1 (vía OpenF1).</p><ul>${rows}</ul>` +
        `<p style="color:#888">Solo los clips que F1 eligió publicar. Escucha el audio antes de citar: los audios son de F1, cita frases cortas con atribución y no republiques el MP3.</p>`,
} }];
